<?php namespace App\Models\CountyServices; use App\Models\County; use Illuminate\Database\Eloquent\Model;
class CountyService extends Model { protected $table='sector_entities'; protected $fillable=['county_id','sector_id','entity_type','entity_id','name','description','sector_type','capture_status','sponsor_funder_tag','latitude','longitude','contact_info','social_links','is_published','language_primary','tags','verification_owner','verification_date']; protected $casts=['is_published'=>'boolean','latitude'=>'float','longitude'=>'float','tags'=>'json','social_links'=>'json']; public function county(){return $this->belongsTo(County::class);} }
